using System.Text.Json;using LibraryApi.Models;namespace LibraryApi.Repositories;public class JsonBookRepository{private readonly string path=Path.Combine(AppContext.BaseDirectory,"Data","books.json");private readonly object gate=new();private List<Book> Read(){Directory.CreateDirectory(Path.GetDirectoryName(path)!);if(!File.Exists(path))File.WriteAllText(path,"[]");return JsonSerializer.Deserialize<List<Book>>(File.ReadAllText(path),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??new();}private void Write(List<Book> x)=>File.WriteAllText(path,JsonSerializer.Serialize(x,new JsonSerializerOptions{WriteIndented=true}));public List<Book> All(){lock(gate)return Read();}public Book? Get(int id){lock(gate)return Read().FirstOrDefault(x=>x.Id==id);}public Book Add(Book b){lock(gate){var x=Read();b.Id=x.Count==0?1:x.Max(y=>y.Id)+1;x.Add(b);Write(x);return b;}}public bool Update(int id,Book b){lock(gate){var x=Read();var i=x.FindIndex(y=>y.Id==id);if(i<0)return false;b.Id=id;x[i]=b;Write(x);return true;}}public bool Delete(int id){lock(gate){var x=Read();var b=x.FirstOrDefault(y=>y.Id==id);if(b==null)return false;x.Remove(b);Write(x);return true;}}}
